package com.cg.pixelguardian;
import android.content.*;import android.content.pm.*;import android.app.*;import android.os.*;import androidx.work.*;import java.util.*;
public class GuardianAudit extends Worker {
 public GuardianAudit(Context c,WorkerParameters p){super(c,p);}
 static final String TARGET="com.cguice49.foresiva";
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("guardian_audit",0);}
 static String fingerprint(Context c)throws Exception{PackageInfo p=c.getPackageManager().getPackageInfo(TARGET,Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES);Signature[] a=Build.VERSION.SDK_INT>=28?p.signingInfo.getApkContentsSigners():p.signatures;TreeSet<String> hashes=new TreeSet<>();for(Signature s:a){StringBuilder b=new StringBuilder();for(byte x:java.security.MessageDigest.getInstance("SHA-256").digest(s.toByteArray()))b.append(String.format(Locale.ROOT,"%02x",x&255));hashes.add(b.toString());}if(hashes.isEmpty())throw new Exception("No signer");return hashes.toString();}
 static String baseline(Context c)throws Exception{String s=fingerprint(c);prefs(c).edit().putString("baseline",s).apply();return s;}
 static synchronized void record(Context c,String line){SharedPreferences p=prefs(c);String h=new java.util.Date()+" — "+line+"\n"+p.getString("history","");p.edit().putString("history",h.substring(0,Math.min(30000,h.length()))).apply();}
 static String audit(Context c){String result;boolean alert=false;try{String now=fingerprint(c);String old=prefs(c).getString("baseline","");if(old.isEmpty())result="Foresiva visible; no trusted baseline enrolled";else if(!old.equals(now)){result="Foresiva signer changed; verify update or key rotation";alert=true;}else result="Foresiva signer matches enrolled baseline";if(c.getPackageManager().getLaunchIntentForPackage(TARGET)==null){result+="; launcher unavailable";alert=true;}}catch(Exception e){result="Foresiva unavailable or signer unreadable";alert=true;}try{java.time.LocalDate patch=java.time.LocalDate.parse(Build.VERSION.SECURITY_PATCH);long age=java.time.temporal.ChronoUnit.DAYS.between(patch,java.time.LocalDate.now());if(age>90){result+="; security patch older than 90 days";alert=true;}}catch(Exception ignored){result+="; patch age unavailable";}result+="; patch "+Build.VERSION.SECURITY_PATCH;try{result+="; "+SixthSense.scan(c);}catch(Exception e){result+="; Sixth Sense scan incomplete";}prefs(c).edit().putLong("last_audit",System.currentTimeMillis()).apply();record(c,result);if(alert)notifyUser(c,result);return result;}
 static void notifyUser(Context c,String text){try{NotificationManager m=c.getSystemService(NotificationManager.class);m.createNotificationChannel(new NotificationChannel("guardian_alerts","Guardian security alerts",NotificationManager.IMPORTANCE_DEFAULT));if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)return;PendingIntent pi=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);m.notify(31,new Notification.Builder(c,"guardian_alerts").setSmallIcon(android.R.drawable.ic_dialog_alert).setContentTitle("Guardian security review").setContentText("Open Guardian to review Foresiva").setContentIntent(pi).setAutoCancel(true).build());}catch(Exception ignored){}}
 @Override public Result doWork(){audit(getApplicationContext());return Result.success();}
}